"""Install CodeGuardian AI pre-push hook into a Git repository.

Default mode is warn-only: developers can push feature branches, while CodeGuardian
blocks unsafe code at Merge Request time. Use --block-push to restore local push blocking.
"""
from __future__ import annotations

import argparse
import os
from pathlib import Path
import stat
import sys


HOOK_TEMPLATE = """#!/usr/bin/env bash
# CodeGuardian AI pre-push hook (auto-generated by scripts/install_pre_push_hook.py).
# Default: warn-only. Merge Requests are blocked by GitLab webhook/CI.
set -uo pipefail

CODEGUARDIAN_HOME="{codeguardian_home}"
CODEGUARDIAN_API="${{CODEGUARDIAN_API:-{api_url}}}"
CODEGUARDIAN_API_TOKEN="${{CODEGUARDIAN_API_TOKEN:-{api_token}}}"
CODEGUARDIAN_PYTHON="${{CODEGUARDIAN_PYTHON:-{python_bin}}}"
CODEGUARDIAN_BLOCK_PUSH="${{CODEGUARDIAN_BLOCK_PUSH:-{block_push}}}"

export PYTHONPATH="$CODEGUARDIAN_HOME${{PYTHONPATH:+:$PYTHONPATH}}"

ARGS=(scan --pre-push --origin pre-push)
if [ "$CODEGUARDIAN_BLOCK_PUSH" != "1" ]; then
  ARGS+=(--warn-only)
fi
if [ -n "$CODEGUARDIAN_API" ]; then
  ARGS+=(--api "$CODEGUARDIAN_API")
fi
if [ -n "$CODEGUARDIAN_API_TOKEN" ]; then
  ARGS+=(--api-token "$CODEGUARDIAN_API_TOKEN")
fi

"$CODEGUARDIAN_PYTHON" -m app.cli "${{ARGS[@]}}"
RC=$?
if [ $RC -ne 0 ]; then
  echo "" >&2
  echo "✖ CodeGuardian AI: push отклонён. Исправьте находки выше или используйте --no-verify только с разрешения security." >&2
  exit $RC
fi
"""


def main() -> int:
    parser = argparse.ArgumentParser(description="Install CodeGuardian AI pre-push hook into a Git repository")
    parser.add_argument("--repo", default=".", help="Path to target Git repository. Default: current directory.")
    parser.add_argument(
        "--codeguardian-home",
        default=str(Path(__file__).resolve().parents[1]),
        help="Path to CodeGuardian AI project root.",
    )
    parser.add_argument(
        "--api",
        default=os.environ.get("CODEGUARDIAN_API", "http://localhost:8000"),
        help="CodeGuardian server URL (use empty string '' to install local-only hook).",
    )
    parser.add_argument(
        "--api-token",
        default=os.environ.get("CODEGUARDIAN_API_TOKEN", ""),
        help="Optional X-CodeGuardian-Token (only needed if precheck is non-public).",
    )
    parser.add_argument(
        "--python",
        default=os.environ.get("CODEGUARDIAN_PYTHON", sys.executable or "python"),
        help="Python interpreter used by the hook.",
    )
    parser.add_argument(
        "--block-push",
        action="store_true",
        help="Reject unsafe pushes locally. Default is warn-only and MR blocking.",
    )
    args = parser.parse_args()

    repo = Path(args.repo).resolve()
    git_dir = repo / ".git"
    if not git_dir.exists():
        print(f"Not a Git repository: {repo}", file=sys.stderr)
        return 2

    hooks_dir = git_dir / "hooks"
    hooks_dir.mkdir(parents=True, exist_ok=True)
    hook_path = hooks_dir / "pre-push"
    if hook_path.exists():
        backup = hooks_dir / "pre-push.codeguardian-backup"
        backup.write_text(hook_path.read_text(encoding="utf-8", errors="replace"), encoding="utf-8")

    codeguardian_home = str(Path(args.codeguardian_home).resolve()).replace("\\", "/")
    python_bin = str(args.python).replace("\\", "/")
    hook_path.write_text(
        HOOK_TEMPLATE.format(
            codeguardian_home=codeguardian_home,
            api_url=args.api or "",
            api_token=args.api_token or "",
            python_bin=python_bin,
            block_push="1" if args.block_push else "0",
        ),
        encoding="utf-8",
        newline="\n",
    )
    hook_path.chmod(hook_path.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    print(f"Installed CodeGuardian pre-push hook: {hook_path}")
    if args.api:
        print(f"  API endpoint: {args.api}/api/git/precheck (fallback to local scanner on failure)")
    else:
        print("  Mode: local scanner only (no API URL configured)")
    print(f"  Push policy: {'block unsafe pushes' if args.block_push else 'warn-only, block on Merge Request'}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
